// Renders project cards from projects.json (generated by scripts/assemble.mjs).
(async () => {
  const list = document.getElementById('projects');
  const empty = document.getElementById('empty');

  let projects = [];
  try {
    const res = await fetch('projects.json', { cache: 'no-cache' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    projects = await res.json();
    if (!Array.isArray(projects)) projects = [];
  } catch (err) {
    console.error('Could not load projects.json', err);
  }

  if (projects.length === 0) {
    empty.hidden = false;
    return;
  }

  const el = (tag, props = {}, children = []) => {
    const node = Object.assign(document.createElement(tag), props);
    for (const child of children) if (child) node.append(child);
    return node;
  };

  for (const p of projects) {
    const title = p.title || p.slug;

    const thumb = el('div', { className: 'thumb' });
    if (p.thumbnail) {
      const img = el('img', { src: p.thumbnail, alt: '', loading: 'lazy', decoding: 'async' });
      img.addEventListener('error', () => {
        thumb.classList.add('fallback');
        thumb.textContent = title.charAt(0).toUpperCase();
      });
      thumb.append(img);
    } else {
      thumb.classList.add('fallback');
      thumb.textContent = title.charAt(0).toUpperCase();
    }

    const card = el('a', { className: 'card', href: p.url }, [
      thumb,
      el('div', { className: 'body' }, [
        el('h3', { textContent: title }),
        p.description ? el('p', { className: 'desc', textContent: p.description }) : null,
      ]),
    ]);

    list.append(el('li', {}, [card]));
  }
})();
